import React from 'react';
import { Home, Beer, Users, Plus, User, LogOut, Settings } from 'lucide-react';

const Navigation = ({ currentPage, handleNavigation, isLoggedIn, user, handleLogout }) => {
  return (
    <nav className="bg-white shadow-lg border-b-4 border-red-600">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center h-16">
          {/* Logo */}
          <div className="flex items-center">
            <img src="/logo.png" alt="Red Robin Brewing" className="h-8 w-8 mr-3" />
            <span className="text-xl font-bold text-gray-900 font-serif">Red Robin Brewing</span>
          </div>

          {/* Main Navigation */}
          <div className="flex items-center space-x-4">
            <button
              onClick={() => handleNavigation('home')}
              className={`flex items-center gap-2 px-4 py-2 rounded-lg font-medium transition-colors ${
                currentPage === 'home'
                  ? 'bg-red-600 text-white'
                  : 'text-gray-700 hover:text-red-600'
              }`}
            >
              <Home className="w-4 h-4" />
              Home
            </button>

            <button
              onClick={() => handleNavigation('beers')}
              className={`flex items-center gap-2 px-4 py-2 rounded-lg font-medium transition-colors ${
                currentPage === 'beers'
                  ? 'bg-red-600 text-white'
                  : 'text-gray-700 hover:text-red-600'
              }`}
            >
              <Beer className="w-4 h-4" />
              Beers
            </button>

            <button
              onClick={() => handleNavigation('friends')}
              className={`flex items-center gap-2 px-4 py-2 rounded-lg font-medium transition-colors ${
                currentPage === 'friends'
                  ? 'bg-red-600 text-white'
                  : 'text-gray-700 hover:text-red-600'
              }`}
            >
              <Users className="w-4 h-4" />
              Friends
            </button>

            {isLoggedIn && (
              <button
                onClick={() => handleNavigation('add-beer')}
                className={`flex items-center gap-2 px-4 py-2 rounded-lg font-medium transition-colors ${
                  currentPage === 'add-beer'
                    ? 'bg-red-600 text-white'
                    : 'text-gray-700 hover:text-red-600'
                }`}
              >
                <Plus className="w-4 h-4" />
                Add Beer
              </button>
            )}

            {/* Admin Link - Only show for admin users */}
            {isLoggedIn && user?.isAdmin && (
              <button
                onClick={() => handleNavigation('admin')}
                className={`flex items-center gap-2 px-4 py-2 rounded-lg font-medium transition-colors ${
                  currentPage === 'admin'
                    ? 'bg-red-600 text-white'
                    : 'text-gray-700 hover:text-red-600'
                }`}
              >
                <Settings className="w-4 h-4" />
                Admin
              </button>
            )}
          </div>

          {/* User Menu */}
          <div className="flex items-center space-x-4">
            {isLoggedIn ? (
              <>
                <button
                  onClick={() => handleNavigation('profile')}
                  className={`flex items-center gap-2 px-4 py-2 rounded-lg font-medium transition-colors ${
                    currentPage === 'profile'
                      ? 'bg-red-600 text-white'
                      : 'text-gray-700 hover:text-red-600'
                  }`}
                >
                  <User className="w-4 h-4" />
                  Profile
                </button>
                <button
                  onClick={handleLogout}
                  className="flex items-center gap-2 px-4 py-2 rounded-lg font-medium text-gray-700 hover:text-red-600 transition-colors"
                >
                  <LogOut className="w-4 h-4" />
                  Logout
                </button>
              </>
            ) : (
              <>
                <button
                  onClick={() => handleNavigation('login')}
                  className={`px-4 py-2 rounded-lg font-medium transition-colors ${
                    currentPage === 'login'
                      ? 'bg-red-600 text-white'
                      : 'text-gray-700 hover:text-red-600'
                  }`}
                >
                  Login
                </button>
                <button
                  onClick={() => handleNavigation('register')}
                  className={`px-4 py-2 rounded-lg font-medium transition-colors ${
                    currentPage === 'register'
                      ? 'bg-red-600 text-white'
                      : 'text-gray-700 hover:text-red-600'
                  }`}
                >
                  Register
                </button>
              </>
            )}
          </div>
        </div>
      </div>
    </nav>
  );
};

export default Navigation;
